def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation from s_in to s_out."""
    # Simple approach: find first position where characters differ
    for i, (char_in, char_out) in enumerate(zip(s_in, s_out)):
        if char_in != char_out:
            # Check if we're replacing a substring
            if len(s_in) == len(s_out):
                # Same length - likely single character replacement
                return (char_in, char_out, i)
            else:
                # Different lengths - might be insertion/deletion
                # For now, let's assume we're looking at the first difference
                return (char_in, char_out, i)

    # If strings are same length but we didn't find differences, 
    # check if one is shorter (insertion case)
    if len(s_in) > len(s_out):
        # Deletion case
        return (s_in[len(s_out)], '', len(s_out))
    elif len(s_in) < len(s_out):
        # Insertion case  
        return ('', s_out[len(s_in)], len(s_in))
    else:
        # No differences found
        return ('', '', -1)

